const items = $input.all().map(i => i.json);

function splitList(value) {
  if (!value) return [];
  return String(value)
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);
}

function norm(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

const equipo = [];
const proyectos = [];
const tareas = [];

for (const item of items) {
  if (item.persona_id) {
    equipo.push({
      persona_id: String(item.persona_id).trim(),
      nombre: String(item.nombre || '').trim(),
      rol: String(item.rol || '').trim(),
      seniority: String(item.seniority || '').trim(),
      skills: splitList(item.skills),
      skills_norm: splitList(item.skills).map(norm),
      capacidad_horas_semana: Number(item.capacidad_horas_semana || 0),
      disponibilidad: String(item.disponibilidad || '').trim(),
      disponible: norm(item.disponibilidad) === 'disponible',
      observaciones: item.observaciones || '',
    });
  }

  if (item.proyecto_id && !item.tarea_id) {
    proyectos.push({
      proyecto_id: String(item.proyecto_id).trim(),
      nombre: String(item.nombre || '').trim(),
      cliente: String(item.cliente || '').trim(),
      prioridad: Number(item.prioridad || 0),
      fecha_inicio: item.fecha_inicio || '',
      deadline: item.deadline || '',
      estado: String(item.estado || '').trim(),
      activo: norm(item.estado) === 'activo',
      horas_estimadas: Number(item.horas_estimadas || 0),
      observaciones: item.observaciones || '',
    });
  }

  if (item.tarea_id) {
    tareas.push({
      tarea_id: String(item.tarea_id).trim(),
      proyecto_id: String(item.proyecto_id || '').trim(),
      nombre: String(item.nombre || '').trim(),
      descripcion: item.descripcion || '',
      skills_requeridas: splitList(item.skills_requeridas),
      skills_requeridas_norm: splitList(item.skills_requeridas).map(norm),
      horas_estimadas: Number(item.horas_estimadas || 0),
      prioridad: Number(item.prioridad || 0),
      deadline: item.deadline || '',
      dependencias: splitList(item.dependencias),
      bloqueada: norm(item.bloqueada) === 'si' || norm(item.bloqueada) === 'sí',
      persona_preferida: String(item.persona_preferida || '').trim(),
    });
  }
}

const proyectoById = Object.fromEntries(
  proyectos.map(p => [p.proyecto_id, p])
);

const equipoByNombre = Object.fromEntries(
  equipo.map(p => [norm(p.nombre), p])
);

const tareasPreparadas = tareas.map(t => {
  const proyecto = proyectoById[t.proyecto_id] || {};
  const preferida = equipoByNombre[norm(t.persona_preferida)];

  return {
    ...t,
    proyecto_nombre: proyecto.nombre || '',
    cliente: proyecto.cliente || '',
    prioridad_proyecto: proyecto.prioridad || 0,
    deadline_proyecto: proyecto.deadline || '',
    persona_preferida_id: preferida?.persona_id || '',
    persona_preferida_existe: Boolean(preferida),
  };
});

const resumen = {
  total_personas: equipo.length,
  total_proyectos: proyectos.length,
  total_tareas: tareas.length,
  horas_totales_tareas: tareas.reduce((sum, t) => sum + t.horas_estimadas, 0),
  capacidad_total_semanal: equipo.reduce((sum, p) => sum + p.capacidad_horas_semana, 0),
  tareas_bloqueadas: tareas.filter(t => t.bloqueada).length,
};

return [
  {
    json: {
      equipo,
      proyectos,
      tareas: tareasPreparadas,
      resumen_input: resumen,
    },
  },
];

const input = $input.first().json;

const data = Array.isArray(input) ? input[0] : input;

const equipo = data.equipo || [];
const proyectos = data.proyectos || [];
const tareas = data.tareas || [];

const PERIODO = data.periodo || 'junio_2026';

function norm(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
}

function asArray(value) {
  if (Array.isArray(value)) return value;
  if (!value) return [];
  return String(value)
    .split(',')
    .map(v => v.trim())
    .filter(Boolean);
}

function dateValue(value) {
  if (!value) return 9999999999999;
  return new Date(value).getTime();
}

function seniorityBonus(seniority) {
  const s = norm(seniority);
  if (s === 'senior') return 20;
  if (s === 'mid') return 10;
  if (s === 'junior') return 0;
  return 0;
}

const personas = equipo
  .filter(p => p.disponible !== false && norm(p.disponibilidad) !== 'no disponible')
  .map(p => ({
    ...p,
    skills_norm: p.skills_norm || asArray(p.skills).map(norm),
    horas_asignadas: 0,
    tareas: [],
  }));

const personaById = Object.fromEntries(personas.map(p => [p.persona_id, p]));
const personaByName = Object.fromEntries(personas.map(p => [norm(p.nombre), p]));

const proyectoById = Object.fromEntries(proyectos.map(p => [p.proyecto_id, p]));

const tareasOrdenadas = [...tareas]
  .filter(t => !t.bloqueada)
  .sort((a, b) => {
    const prioridadA = Number(a.prioridad || 0) + Number(a.prioridad_proyecto || 0);
    const prioridadB = Number(b.prioridad || 0) + Number(b.prioridad_proyecto || 0);

    if (prioridadB !== prioridadA) return prioridadB - prioridadA;

    return dateValue(a.deadline) - dateValue(b.deadline);
  });

const asignaciones = [];
const advertencias = [];

function evaluarPersona(tarea, persona) {
  const requeridas = tarea.skills_requeridas_norm || asArray(tarea.skills_requeridas).map(norm);
  const personaSkills = persona.skills_norm || [];

  const matched = requeridas.filter(s => personaSkills.includes(s));
  const missing = requeridas.filter(s => !personaSkills.includes(s));

  const horas = Number(tarea.horas_estimadas || 0);
  const capacidadRestante = Number(persona.capacidad_horas_semana || 0) - Number(persona.horas_asignadas || 0);

  const personaPreferidaId = tarea.persona_preferida_id;
  const personaPreferidaNombre = norm(tarea.persona_preferida);

  const esPreferida =
    personaPreferidaId === persona.persona_id ||
    personaPreferidaNombre === norm(persona.nombre);

  let score = 0;

  score += matched.length * 40;
  score -= missing.length * 35;
  score += seniorityBonus(persona.seniority);
  score += esPreferida ? 35 : 0;

  if (capacidadRestante >= horas) {
    score += 50;
  } else {
    score -= Math.abs(capacidadRestante - horas) * 12;
  }

  score += Number(tarea.prioridad || 0) * 5;
  score += Number(tarea.prioridad_proyecto || 0) * 5;

  return {
    persona,
    score,
    matched,
    missing,
    capacidadRestante,
    cabe: capacidadRestante >= horas,
    esPreferida,
  };
}

for (const tarea of tareasOrdenadas) {
  const horas = Number(tarea.horas_estimadas || 0);

  let candidatos = personas
    .map(persona => evaluarPersona(tarea, persona))
    .filter(c => c.cabe);

  if (candidatos.length === 0) {
    asignaciones.push({
      tarea_id: tarea.tarea_id,
      tarea: tarea.nombre,
      proyecto_id: tarea.proyecto_id,
      proyecto: tarea.proyecto_nombre || proyectoById[tarea.proyecto_id]?.nombre || '',
      cliente: tarea.cliente || proyectoById[tarea.proyecto_id]?.cliente || '',
      persona_id: '',
      persona: '',
      rol: '',
      seniority: '',
      estado_asignacion: 'sin_asignar',
      horas_estimadas: horas,
      deadline: tarea.deadline,
      prioridad: tarea.prioridad,
      skills_requeridas: asArray(tarea.skills_requeridas).join(', '),
      skills_match: '',
      score_asignacion: '',
      motivo: 'Sin persona con capacidad suficiente',
    });

    advertencias.push({
      tipo: 'TAREA_SIN_ASIGNAR',
      tarea_id: tarea.tarea_id,
      tarea: tarea.nombre,
      detalle: `No hay capacidad suficiente para ${horas}h`,
    });

    continue;
  }

  candidatos.sort((a, b) => b.score - a.score);

  const elegido = candidatos[0];
  const persona = elegido.persona;

  persona.horas_asignadas += horas;
  persona.tareas.push(tarea.tarea_id);

  const proyecto = proyectoById[tarea.proyecto_id] || {};

  asignaciones.push({
    tarea_id: tarea.tarea_id,
    tarea: tarea.nombre,
    proyecto_id: tarea.proyecto_id,
    proyecto: tarea.proyecto_nombre || proyecto.nombre || '',
    cliente: tarea.cliente || proyecto.cliente || '',
    persona_id: persona.persona_id,
    persona: persona.nombre,
    rol: persona.rol,
    seniority: persona.seniority,
    estado_asignacion: 'asignada',
    horas_estimadas: horas,
    deadline: tarea.deadline,
    prioridad: tarea.prioridad,
    skills_requeridas: asArray(tarea.skills_requeridas).join(', '),
    skills_match: elegido.matched.join(', '),
    score_asignacion: elegido.score,
    motivo: elegido.esPreferida
      ? 'Asignada a persona preferida viable'
      : 'Asignada por mejor encaje skills/capacidad',
  });

  if (elegido.missing.length > 0) {
    advertencias.push({
      tipo: 'SKILLS_INCOMPLETAS',
      tarea_id: tarea.tarea_id,
      tarea: tarea.nombre,
      persona: persona.nombre,
      detalle: `Faltan skills: ${elegido.missing.join(', ')}`,
    });
  }
}

const resumenPersonas = personas.map(p => {
  const capacidad = Number(p.capacidad_horas_semana || 0);
  const asignado = Number(p.horas_asignadas || 0);

  if (asignado > capacidad) {
    advertencias.push({
      tipo: 'SOBRECARGA_PERSONA',
      persona_id: p.persona_id,
      persona: p.nombre,
      capacidad,
      asignado,
      exceso: asignado - capacidad,
    });
  }

  return {
    persona_id: p.persona_id,
    nombre: p.nombre,
    rol: p.rol,
    capacidad_horas_semana: capacidad,
    horas_asignadas: asignado,
    horas_libres: capacidad - asignado,
    porcentaje_ocupacion: capacidad > 0 ? Math.round((asignado / capacidad) * 100) : 0,
    num_tareas: p.tareas.length,
    tareas: p.tareas.join(', '),
  };
});

const resumenProyectos = proyectos.map(proyecto => {
  const tareasProyecto = tareas.filter(t => t.proyecto_id === proyecto.proyecto_id);
  const asignadasProyecto = asignaciones.filter(
    a => a.proyecto_id === proyecto.proyecto_id && a.estado_asignacion === 'asignada'
  );

  return {
    proyecto_id: proyecto.proyecto_id,
    nombre: proyecto.nombre,
    cliente: proyecto.cliente,
    prioridad: proyecto.prioridad,
    deadline: proyecto.deadline,
    total_tareas: tareasProyecto.length,
    tareas_asignadas: asignadasProyecto.length,
    tareas_sin_asignar: tareasProyecto.length - asignadasProyecto.length,
    horas_asignadas: asignadasProyecto.reduce((sum, a) => sum + Number(a.horas_estimadas || 0), 0),
  };
});

const resumen = {
  total_tareas: tareas.length,
  tareas_asignadas: asignaciones.filter(a => a.estado_asignacion === 'asignada').length,
  tareas_sin_asignar: asignaciones.filter(a => a.estado_asignacion === 'sin_asignar').length,
  total_advertencias: advertencias.length,
  horas_totales_asignadas: asignaciones.reduce((sum, a) => {
    if (a.estado_asignacion !== 'asignada') return sum;
    return sum + Number(a.horas_estimadas || 0);
  }, 0),
  capacidad_total: personas.reduce((sum, p) => sum + Number(p.capacidad_horas_semana || 0), 0),
};

return [
  {
    json: {
      periodo: PERIODO,
      asignaciones,
      resumen_personas: resumenPersonas,
      resumen_proyectos: resumenProyectos,
      advertencias,
      resumen,
      input_original: data,
    },
  },
];

const input = $input.first().json;
const data = Array.isArray(input) ? input[0] : input;

const now = new Date();

const periodo = data.periodo || 'periodo_sin_nombre';
const asignaciones = data.asignaciones || [];
const resumenPersonas = data.resumen_personas || [];
const resumenProyectos = data.resumen_proyectos || [];
const advertencias = data.advertencias || [];
const resumen = data.resumen || {};

function row(seccion, c1 = '', c2 = '', c3 = '', c4 = '', c5 = '', c6 = '', c7 = '', c8 = '') {
  return {
    periodo,
    created_at: now.toISOString(),
    seccion,
    col_1: c1,
    col_2: c2,
    col_3: c3,
    col_4: c4,
    col_5: c5,
    col_6: c6,
    col_7: c7,
    col_8: c8,
  };
}

const rows = [];

// =====================
// RESUMEN GENERAL
// =====================

rows.push(row('titulo', 'INFORME ASIGNACIÓN PROYECTOS'));
rows.push(row('metadata', 'periodo', periodo));
rows.push(row('metadata', 'created_at', now.toISOString()));
rows.push(row(''));

rows.push(row('resumen_general', 'RESUMEN GENERAL'));
rows.push(row('resumen_general', 'total tareas', resumen.total_tareas ?? asignaciones.length));
rows.push(row('resumen_general', 'tareas asignadas', resumen.tareas_asignadas ?? asignaciones.filter(a => a.estado_asignacion === 'asignada').length));
rows.push(row('resumen_general', 'tareas sin asignar', resumen.tareas_sin_asignar ?? asignaciones.filter(a => a.estado_asignacion === 'sin_asignar').length));
rows.push(row('resumen_general', 'horas asignadas', resumen.horas_totales_asignadas ?? ''));
rows.push(row('resumen_general', 'capacidad total', resumen.capacidad_total ?? ''));
rows.push(row('resumen_general', 'advertencias', resumen.total_advertencias ?? advertencias.length));
rows.push(row(''));

// =====================
// ASIGNACIONES
// =====================

rows.push(row('asignaciones', 'ASIGNACIONES'));
rows.push(row(
  'asignaciones',
  'tarea_id',
  'tarea',
  'proyecto',
  'persona',
  'horas',
  'deadline',
  'skills match',
  'motivo'
));

for (const a of asignaciones.filter(x => x.estado_asignacion === 'asignada')) {
  rows.push(row(
    'asignaciones',
    a.tarea_id || '',
    a.tarea || '',
    a.proyecto || '',
    a.persona || '',
    a.horas_estimadas ?? '',
    a.deadline || '',
    a.skills_match || '',
    a.motivo || ''
  ));
}

rows.push(row(''));

// =====================
// TAREAS SIN ASIGNAR
// =====================

rows.push(row('sin_asignar', 'TAREAS SIN ASIGNAR'));
rows.push(row(
  'sin_asignar',
  'tarea_id',
  'tarea',
  'proyecto',
  'horas',
  'deadline',
  'prioridad',
  'skills requeridas',
  'motivo'
));

for (const a of asignaciones.filter(x => x.estado_asignacion === 'sin_asignar')) {
  rows.push(row(
    'sin_asignar',
    a.tarea_id || '',
    a.tarea || '',
    a.proyecto || '',
    a.horas_estimadas ?? '',
    a.deadline || '',
    a.prioridad ?? '',
    a.skills_requeridas || '',
    a.motivo || ''
  ));
}

rows.push(row(''));

// =====================
// CARGA POR PERSONA
// =====================

rows.push(row('personas', 'CARGA POR PERSONA'));
rows.push(row(
  'personas',
  'persona',
  'rol',
  'capacidad',
  'horas asignadas',
  'horas libres',
  '% ocupación',
  'nº tareas',
  'tareas'
));

for (const p of resumenPersonas) {
  rows.push(row(
    'personas',
    p.nombre || '',
    p.rol || '',
    p.capacidad_horas_semana ?? '',
    p.horas_asignadas ?? '',
    p.horas_libres ?? '',
    p.porcentaje_ocupacion ?? '',
    p.num_tareas ?? '',
    p.tareas || ''
  ));
}

rows.push(row(''));

// =====================
// RESUMEN POR PROYECTO
// =====================

rows.push(row('proyectos', 'RESUMEN POR PROYECTO'));
rows.push(row(
  'proyectos',
  'proyecto',
  'cliente',
  'prioridad',
  'deadline',
  'total tareas',
  'asignadas',
  'sin asignar',
  'horas asignadas'
));

for (const p of resumenProyectos) {
  rows.push(row(
    'proyectos',
    p.nombre || '',
    p.cliente || '',
    p.prioridad ?? '',
    p.deadline || '',
    p.total_tareas ?? '',
    p.tareas_asignadas ?? '',
    p.tareas_sin_asignar ?? '',
    p.horas_asignadas ?? ''
  ));
}

rows.push(row(''));

// =====================
// ADVERTENCIAS
// =====================

rows.push(row('advertencias', 'ADVERTENCIAS'));
rows.push(row(
  'advertencias',
  'tipo',
  'tarea_id/persona_id',
  'tarea/persona',
  'detalle',
  '',
  '',
  '',
  ''
));

for (const a of advertencias) {
  rows.push(row(
    'advertencias',
    a.tipo || '',
    a.tarea_id || a.persona_id || '',
    a.tarea || a.persona || '',
    a.detalle || `Capacidad ${a.capacidad ?? ''}, asignado ${a.asignado ?? ''}, exceso ${a.exceso ?? ''}`,
    '',
    '',
    '',
    ''
  ));
}

rows.push(row(''));

// =====================
// RECOMENDACIONES
// =====================

const tareasSinAsignar = asignaciones.filter(a => a.estado_asignacion === 'sin_asignar');
const personasConHueco = resumenPersonas.filter(p => Number(p.horas_libres || 0) > 0);

rows.push(row('recomendaciones', 'RECOMENDACIONES'));

if (tareasSinAsignar.length > 0) {
  rows.push(row(
    'recomendaciones',
    'Hay tareas sin asignar',
    `${tareasSinAsignar.length} tareas no caben con la capacidad individual actual`
  ));

  rows.push(row(
    'recomendaciones',
    'Dividir tareas grandes',
    'Partir tareas de 14h o más en subtareas pequeñas para aprovechar huecos libres'
  ));

  rows.push(row(
    'recomendaciones',
    'Permitir sobrecarga controlada',
    'Añadir una opción de tolerancia, por ejemplo +10% o +20% de capacidad'
  ));

  rows.push(row(
    'recomendaciones',
    'Revisar skills incompletas',
    'Algunas asignaciones son viables por capacidad pero no cubren todas las skills'
  ));
} else {
  rows.push(row(
    'recomendaciones',
    'Asignación completa',
    'Todas las tareas han sido asignadas'
  ));
}

if (personasConHueco.length > 0) {
  rows.push(row(
    'recomendaciones',
    'Capacidad libre disponible',
    personasConHueco.map(p => `${p.nombre}: ${p.horas_libres}h`).join(', ')
  ));
}

rows.push(row(''));

// =====================
// JSON ORIGINAL
// =====================

rows.push(row('json', 'JSON RESULTADO'));
rows.push(row('json', 'json_resultado', JSON.stringify(data)));

return rows.map(r => ({ json: r }));
